const resourceNameTaken = `-- name: ResourceNameTaken :one
SELECT EXISTS (
    SELECT 1 FROM resources
    WHERE organization_id = $1
      AND branch_id = $2
      AND lower(name) = lower($3)
      AND deleted_at IS NULL
      AND ($4::bigint IS NULL OR id <> $4)
)::boolean
`

